## Массивы + Map / Set

Blind 75 начинается с задач, где за **O(n)** нужно ответить на вопрос «видели ли мы это раньше?» или «какая частота?».

- **`Set`** — быстрая проверка дубликата.
- **`Map`** — значение по ключу (индекс, счётчик, группа).

Комplement для Two Sum: для `nums[i]` ищем `target - nums[i]` в Map.

```javascript
const seen = new Map();
for (let i = 0; i < nums.length; i += 1) {
  const need = target - nums[i];
  if (seen.has(need)) return [seen.get(need), i];
  seen.set(nums[i], i);
}
```

content.referenceSolution:
function hasDuplicate(nums) {
  const seen = new Set();
  for (const x of nums) {
    if (seen.has(x)) return true;
    seen.add(x);
  }
  return false;
}

function containsDuplicate(nums) {
  return new Set(nums).size !== nums.length;
}

function isAnagram(s, t) {
  if (s.length !== t.length) return false;
  const count = new Map();
  for (const c of s) count.set(c, (count.get(c) ?? 0) + 1);
  for (const c of t) {
    const n = count.get(c);
    if (!n) return false;
    if (n === 1) count.delete(c);
    else count.set(c, n - 1);
  }
  return count.size === 0;
}

function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i += 1) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need), i];
    seen.set(nums[i], i);
  }
  return [];
}

function groupAnagrams(strs) {
  const map = new Map();
  for (const s of strs) {
    const key = s.split("").sort().join("");
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(s);
  }
  return [...map.values()];
}

function topKFrequent(nums, k) {
  const freq = new Map();
  for (const n of nums) freq.set(n, (freq.get(n) ?? 0) + 1);
  return [...freq.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, k)
    .map(([n]) => n);
}

function productExceptSelf(nums) {
  const n = nums.length;
  const out = new Array(n);
  out[0] = 1;
  for (let i = 1; i < n; i += 1) out[i] = out[i - 1] * nums[i - 1];
  let suffix = 1;
  for (let i = n - 1; i >= 0; i -= 1) {
    out[i] *= suffix;
    suffix *= nums[i];
  }
  for (let i = 0; i < n; i += 1) nums[i] = out[i];
}

