class Codec {
  encode(strs) {
    return strs.map((str) => `${str.length}#${str}`).join("");
  }
  decode(s) {
    const out = [];
    let i = 0;
    while (i < s.length) {
      let j = i;
      while (s[j] !== "#") j += 1;
      const len = Number(s.slice(i, j));
      out.push(s.slice(j + 1, j + 1 + len));
      i = j + 1 + len;
    }
    return out;
  }
}

